/* 1. Creating the Shared Library (libutil.so) */
// util.c: Must use -fPIC (Position Independent Code)
int shared_operation(int x) { return x * x; }

/* CLI Compilation Command */
gcc -c -fPIC util.c
gcc -shared -o libutil.so util.o

/* 2. Dynamic Linking at Compile Time */
// main.c: Uses the library reference
extern int shared_operation(int);

/* CLI Linking Command */
// -lutil: link against libutil.so
// -L.: Specify library search path (current directory)
gcc main.c -L. -lutil -o app_dyn

/* 3. Runtime Library Resolution Setup */
/* OS Loader must find the .so file at runtime */

/* Environment Variable (Temporary, POSIX) */
export LD_LIBRARY_PATH=$PWD:$LD_LIBRARY_PATH
./app_dyn

/* 4. Explicit Runtime Loading (dlopen/dlsym) */
void* handle = dlopen("libutil.so", RTLD_NOW);
if (!handle) { /* Handle error */ }

// Define function pointer type
typedef int (*SharedFunc)(int);

// Resolve symbol (function address)
SharedFunc func = (SharedFunc)dlsym(handle, "shared_operation");
int result = func(12);

dlclose(handle);
